/// <summary>
/// Generate cryptographically secure random d20 dice rolls.
/// Prevents LLM bias in dice outcomes.
/// </summary>
public static int[] GenerateSecureRandomDice(int count = 20)
{
    if (count <= 0)
        return Array.Empty<int>();

    var dice = new int[count];
    var bytes = new byte[4];

    for (int i = 0; i < count; i++)
    {
        RandomNumberGenerator.Fill(bytes);
        var value = BitConverter.ToUInt32(bytes, 0);
        dice[i] = (int)(value % 20) + 1;
    }

    return dice;
}

/// <summary>
/// Compute the client-side gacha base result from a separate hidden 4d20 roll.
/// This result is intentionally kept separate from the GM-facing dice pool.
/// Rarity thresholds: 4–48 Common, 49–67 Uncommon, 68–75 Rare, 76–79 Epic, 80 Legendary.
/// The GM may only add modifiers on top (guardian reputation, mode bonuses), never reduce.
/// </summary>
public static GachaResult ComputeGachaBase(int[] dice)
{
    if (dice.Length < 4)
        return new GachaResult
        {
            DiceUsed = Array.Empty<int>(),
            BaseScore = 0,
            BaseRarity = "Common",
            Formula = "client-computed gacha base (insufficient internal rolls)"
        };

    var used = new[] { dice[0], dice[1], dice[2], dice[3] };
    int score = used[0] + used[1] + used[2] + used[3];

    string rarity = score switch
    {
        80 => "Legendary",
        >= 76 => "Epic",
        >= 68 => "Rare",
        >= 49 => "Uncommon",
        _ => "Common"
    };

    return new GachaResult
    {
        DiceUsed = Array.Empty<int>(),
        BaseScore = score,
        BaseRarity = rarity,
        Formula = "client-computed gacha base (range 4-80)"
    };
}

private Task EnsureClientOwnedSystemFilesHealthyAsync(bool ordinaryEntry = false)=>
    SessionOperationContext.RunParticipatingCurrentSessionAsync(_fs,()=>EnsureClientOwnedSystemFilesHealthyCoreAsync(ordinaryEntry));
private async Task EnsureClientOwnedSystemFilesHealthyCoreAsync(bool ordinaryEntry)
{
    await CleanupOrphanedTurnRequestBeforeValidationAsync();
    await _stateManager.RefreshGameStateAsync();
    var preserveControlFilesForTerminalValidation =
        await ShouldPreserveClientOwnedControlFilesForTerminalValidationAsync();

    if (ordinaryEntry)
    {
        if (!await WriteGameSettingsForGm())
            throw new InvalidDataException("Синхронизация настроек не подтверждена. Требуется завершить активную запись или восстановление перед продолжением.");
    }
    else
    {
        // B3: accepted-turn/repair receipt workflows retain their existing
        // route until that whole publication boundary is migrated.
        if (await _systemModService.WriteManifestForGmAsync())
            await _stateManager.SaveSettingsAsync();
    }

    await AfterlifeNotificationState.EnsureHealthyAsync(_fs);
    if (!preserveControlFilesForTerminalValidation)
    {
        await _afterlifeReturnGuardService.EnsureHealthyAsync(_stateManager.CurrentState.CurrentRealm);
        await _systemGuardianLibraryService.EnsureAttractionRequestHealthyAsync(_stateManager.CurrentState.CurrentRealm);
    }

    await _qteSceneService.EnsureRuntimeStateHealthyAsync();
    await _progressionSchedule.EnsureInitializedAsync();
}

private async Task CleanupOrphanedTurnRequestBeforeValidationAsync()
{
    if (!_fs.FileExists("input/turn_request.json"))
        return;

    if (HasTerminalReadySignal() ||
        _fs.FileExists(ValidationRepairRequestPath) ||
        _fs.FileExists(ValidationRepairReadyPath))
        return;

    var pendingSnapshot = await ResolveActivePendingTurnSnapshotContextAsync();
    if (pendingSnapshot.Status == PendingTurnSnapshotResolutionStatus.Usable)
        return;

    _logger.LogWarning(
        pendingSnapshot.Status == PendingTurnSnapshotResolutionStatus.Missing
            ? "Найден orphaned input/turn_request.json без pending snapshot manifest перед validation. Удаление как stale runtime artifact."
            : "Найден input/turn_request.json с unreadable/invalid validated pending snapshot authority перед validation. Удаление как stale runtime artifact.");
    _fs.DeleteFile("input/turn_request.json");
}

    private async Task<bool> ValidateCurrentGameStateOrShowErrorsAsync(string source,
        RollbackSnapshot? rollbackSnapshot = null,
        ProgressionControl? progressionControl = null,
        bool allowRepairLoop = false,
        DateTime? initialCanonicalRepairBoundaryUtc = null,
        IReadOnlyCollection<ValidationIssue>? initialCanonicalRepairErrors = null,
        DateTime? initialCanonicalRepairStartedAtUtc = null,
        byte[]? pendingResolutionRepairCheckpoint = null,
        Func<Task>? beforeRepairMutation = null,
        Func<Task>? beforeTerminalRepairReturn = null,
        bool applyProgressionOnSuccess = true,
        MortalWoundTreatmentResourcePublicationTransaction?
            treatmentResourcePublicationTransaction = null,
        ValidationService.GuardianMusingsPublicationCapture.GuardianMusingsCompletedValidation?
            guardianMusingsForRepair = null)
    {
        var repairAttempt = 0;
        List<ValidationIssue>? lastRepairErrors = null;
        IReadOnlyCollection<ValidationIssue>? outputFreshnessRepairErrors = initialCanonicalRepairErrors;
        var lastRepairAttempt = 0;
        var lastCanonicalRepairBoundaryUtc = initialCanonicalRepairBoundaryUtc;
        DateTime? lastCanonicalRepairStartedAtUtc = initialCanonicalRepairStartedAtUtc;
        string? lastRepairSessionGeneration = null;
        var repairMutationPrepared = false;
        var repairResubmissionCompleted = false;

        while (true)
        {
            await EnsureClientOwnedSystemFilesHealthyAsync();
            // Install in this flow after the fresh read-only lease has closed.
            // Each genuine repair completion permits exactly one validation iteration.
            using var repairedMusingsScope = repairResubmissionCompleted && guardianMusingsForRepair is not null
                ? _validator.UseCompletedGuardianMusingsValidationScope(
                    await _validator.RecheckOriginalGuardianMusingsAfterRepairAsync(guardianMusingsForRepair))
                : null;
            repairResubmissionCompleted = false;
            List<ValidationIssue> issues;
#if DEBUG
            using (_fs.BrowserDiagnosticLogical(null, source))
#endif
            {
                issues = await _validator.ValidateGameStateAsync();
            }
            if (RequiresAcceptedTurnPayloadValidation(source))
            {
                if (RequiresFreshNarrativePayload(source))
                    issues.AddRange(await _validator.ValidateAcceptedTurnNarrativePayloadAsync());
                issues.AddRange(await _validator.ValidateAcceptedTurnInterfacePayloadAsync());
                issues.AddRange(await _validator.ValidateAcceptedTurnReasoningAsync());
                issues.AddRange(await _validator.ValidateAcceptedTurnSpecialActionOutcomesAsync());
                issues.AddRange(await _validator.ValidateAcceptedTurnQteOfferAsync());
                issues.AddRange(await _validator.ValidateAcceptedTurnMortalCombatMaterializationAsync());
                issues.AddRange(await _validator.ValidateAcceptedTurnMortalLevelUpMaterializationAsync());
            }
            if (allowRepairLoop &&
                outputFreshnessRepairErrors is { Count: > 0 } &&
                lastCanonicalRepairStartedAtUtc.HasValue)
            {
                lastCanonicalRepairBoundaryUtc = ResolveCanonicalRepairOutputFreshnessBoundaryUtc(
                    outputFreshnessRepairErrors,
                    lastCanonicalRepairStartedAtUtc.Value,
                    lastCanonicalRepairBoundaryUtc);
            }
            if (allowRepairLoop &&
                outputFreshnessRepairErrors is { Count: > 0 } &&
                lastCanonicalRepairBoundaryUtc.HasValue)
            {
                issues.AddRange(CollectPlayerFacingOutputStaleAfterCanonicalRepairIssues(
                    outputFreshnessRepairErrors,
                    lastCanonicalRepairBoundaryUtc.Value));
            }
            issues.AddRange(await _validator.ValidatePendingMemoryLegacyApplicationAsync());
            if (progressionControl != null)
                issues.AddRange(await _progressionSchedule.ValidateAcceptedTurnOutcomeAsync(progressionControl));
            if (treatmentResourcePublicationTransaction is not null)
            {
                issues = (await treatmentResourcePublicationTransaction
                    .FilterExactPublishedItemValidationIssuesAsync(_fs, issues))
                    .ToList();
            }
            var errors = PrioritizeValidationErrors(issues.Where(i => i.Severity == IssueSeverity.Error)).ToList();

            if (allowRepairLoop)
                errors = await FilterRestoredForbiddenRealmBaselineErrorsAsync(source, errors);

            if (errors.Count != 0)
                repairedMusingsScope?.Invalidate();

            if (errors.Any(static issue => issue.Code == "spiritual_completed_conflict_validation_mismatch"))
            {
                _logger.LogError("Completed spiritual publication lost its exact validation binding after {Source}.", source);
                if (beforeTerminalRepairReturn is not null)
                    await beforeTerminalRepairReturn();
                return false;
            }

            if (errors.Count == 0)
            {
                if (allowRepairLoop && lastRepairErrors is { Count: > 0 })
                {
                    await AppendClearedValidationRepairTrajectoryAsync(
                        source,
                        lastRepairErrors,
                        lastRepairAttempt,
                        lastRepairSessionGeneration!);
                    await DeleteValidationRepairFilesForSessionAsync(lastRepairSessionGeneration!);
                }
                else
                {
                    await DeleteValidationRepairFilesAsync();
                }
                if (applyProgressionOnSuccess && progressionControl != null)
                    await _progressionSchedule.ApplyAcceptedTurnOutcomeAsync(progressionControl);
                return true;
            }

            if (allowRepairLoop &&
                !repairMutationPrepared &&
                beforeRepairMutation is not null)
            {
                await beforeRepairMutation();
                repairMutationPrepared = true;
            }

            if (allowRepairLoop && await TryAutoRollbackRealmSegregationViolationsAsync(source, errors))
            {
                await RefreshRuntimeStateAsync();
                continue;
            }

            if (allowRepairLoop && await TryAutoRepairStartupGuardianDirectMaterializationAsync(source, errors))
            {
                await RefreshRuntimeStateAsync();
                continue;
            }

            _logger.LogError("Нарушение контракта состояния после {Source}: {Count} ошибок", source, errors.Count);

            if (!allowRepairLoop)
            {
                if (HasRollbackCapability(rollbackSnapshot))
                {
                    await RestorePreTurnBackup(rollbackSnapshot!);
                    CleanupBackup(rollbackSnapshot!);
                }

                await _progressionSchedule.DeleteTransientReportAsync();
                ShowContractValidationErrors(source, errors);
                return false;

private static bool RequiresAcceptedTurnPayloadValidation(string source)
{
    return source is "ответа GM" or "late response GM" or "обработки хода" or "оценки жизни";
}

private void ShowContractValidationErrors(string source, List<ValidationIssue> errors)
{
    foreach (var issue in errors)
    {
        _logger.LogError(
            "Rejected state after {Source}: code={Code}; path={Path}; message={Message}; expected={Expected}; actual={Actual}; repairHint={RepairHint}",
            source,
            issue.Code,
            issue.FilePath,
            issue.Message,
            issue.Expected,
            issue.Actual,
            issue.RepairHint);
    }

    const string playerText =
        "Изменения мира не были приняты. Вернитесь к последнему устойчивому состоянию и повторите действие позже.";
    AnsiConsole.Write(new Panel(GameInterface.SafeMarkup(playerText))
    {
        Header = new PanelHeader(" Ход не принят ", Justify.Center),
        Border = BoxBorder.Double,
        BorderStyle = new Style(Color.Red),
        Padding = new Padding(2, 1),
        Expand = true
    });
    AnsiConsole.MarkupLine($"[grey]{_loc.T("press_any_key")}[/]");

    if (_inputSource is AgentConsoleLiveInputSource liveInput)
    {
        liveInput.PublishSnapshot(new AgentConsoleSnapshot
        {
            ScreenId = PlayerSafePausedScreenId,
            Mode = AgentConsoleMode.Error,
            Title = "Ход не принят",
            PlainText = playerText + Environment.NewLine + _loc.T("press_any_key"),
            AwaitingInput = true,
            InputKind = AgentConsoleInputKind.Key,
            Actions =
            [
                new AgentConsoleAction
                {
                    Id = "continue",
                    Label = "Продолжить",
                    Shortcut = "enter",
                    IsDefault = true
                }
            ],
            RenderedAtUtc = DateTimeOffset.UtcNow,
            UpdatedAtUtc = DateTimeOffset.UtcNow,
            Diagnostics = []
        }, "Течение мира временно приостановлено.");
    }

    _inputSource.ReadKey(intercept: true);
}

internal static bool RequiresWoundRepairFailClosed(
    IReadOnlyList<ValidationIssue> errors,
    bool rollbackAvailable)
{
    ArgumentNullException.ThrowIfNull(errors);
    var actionablePackets = WoundRepairPacketBuilder.Build(errors);
    return WoundRepairPacketBuilder.RequiresFailClosedRollback(errors) ||
           (actionablePackets.Count > 0 && !rollbackAvailable) ||
           errors.Any(static issue => string.Equals(
               issue.Code,
               "wound_repair_retry_authority_unavailable",
               StringComparison.Ordinal));
}

private async Task<string> CaptureCurrentSessionGenerationAsync()
{
    if (SessionOperationContext.TryGetExpectedGeneration(
            _fs.BasePath,
            out var boundSessionGeneration))
    {
        return boundSessionGeneration;
    }

    var writeLease = await _fs.AcquireCanonicalWriteLeaseAsync();
    Exception? publicationFailure = null;
    try { return _fs.GetOrCreateSessionGeneration(writeLease); }
    catch (CoordinatedStatePublicationUncertainException failure)
    {
        publicationFailure = failure;
        throw;
    }
    finally
    {
        await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(
            _fs, writeLease, completed: false, publicationFailure);

    Func<Task>? validatePreparedNamespace = null)
{
    lease.EnsureNoPendingLocalDecision();
    VerifyCurrentSessionOperation(lease);
    if (changes.Count == 0 || changes.Any(change => !UsesTrustedLocalWriter(lease, change.RelativePath)))
        throw new InvalidOperationException("A local publication requires ordinary declared canonical members.");
    var generation = GetOrCreateSessionGeneration(lease);
    return PublishLocalCoreAsync(lease, TrustedLocalGeneration.Existing(generation),
        changes.Select(change => new TrustedLocalFileChange(ResolvePath(change.RelativePath), change.Before, change.After)).ToArray(),
        cancellationToken, validatePreparedNamespace);
}

private async Task<TrustedLocalPublicationOutcome> PublishLocalCoreAsync(CanonicalWriteLease lease,
    TrustedLocalGeneration generation, IReadOnlyList<TrustedLocalFileChange> changes, CancellationToken cancellationToken,
    Func<Task>? validatePreparedNamespace = null, bool standaloneDarenProfile = false)
{
    lease.EnsureNoPendingLocalDecision();
    if (standaloneDarenProfile)
    {
        RequireStandaloneDarenProfile(lease);
        if (changes.Count != 1 || changes[0].Path != RegisteredDarenProfilePath)
            throw new InvalidOperationException("Standalone Daren publication requires its exact registered member.");
    }
    EnsureWorkerPurposePublication(lease, generation, changes);
    if (lease.BrowserLocalAccess is { } browser)
    {
        browser.Validate();
        foreach (var change in changes)
            if (browser.RecordIntent != null) await browser.RecordIntent(change.Path, change.After);
    }
    var scope = new TrustedLocalFileScope([BasePath]);
    var registrations = new List<InProcessMutationRegistration>();
    try
    {
        foreach (var change in changes)
        {
            scope.EnsureDirectory(Path.GetDirectoryName(change.Path)!);
            scope.ValidateFile(change.Path);
            registrations.Add(new InProcessMutationRegistration(change.Path));
        }
        var windows = OperatingSystem.IsWindows();
        var generationPath = TrustedLocalFilePublication.NormalizeAuthorityPath(SessionGenerationPath, windows);
        foreach (var change in changes)
        {
            var memberPath = scope.ValidateFile(change.Path);
            if (string.Equals(memberPath, generationPath,
                    windows ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal)) continue;
            if (lease.BrowserLocalAccess?.ProfilePath == memberPath || standaloneDarenProfile)
            {
                if (standaloneDarenProfile) RequireStandaloneDarenProfile(lease);
                else RequireDeclaredDarenProfile(lease);
                await InvokeBeforeCanonicalMutationBoundaryAsync("@daren_reward_profile");
                scope.ValidateFile(memberPath);
                await InvokeAfterCanonicalMutationBoundaryValidatedAsync("@daren_reward_profile");
                if (standaloneDarenProfile) RequireStandaloneDarenProfile(lease);
                continue;
            }
            var relative = GetLocalRelativePath(GameSessionPath, memberPath, windows);
            var canonicalPath = ResolvePath(relative);
            await InvokeBeforeCanonicalMutationBoundaryAsync(relative);
            EnsureCanonicalMutationBoundary(relative, canonicalPath);
            await InvokeAfterCanonicalMutationBoundaryValidatedAsync(relative);
        }
        cancellationToken.ThrowIfCancellationRequested();
        VerifyCurrentSessionOperation(lease);
        EnsureWorkerPurposePublication(lease, generation, changes);
        var publisher = new TrustedLocalFilePublication(this, scope);
        for (var attempt = 0; ; attempt++)
        {
            EnsureWorkerPurposePublication(lease, generation, changes);
            if (validatePreparedNamespace != null) await validatePreparedNamespace();
            var outcome = publisher.PublishWithOutcome(lease, generation, changes, _hooks?.LocalPublicationObserver);
            if (outcome.Disposition != TrustedLocalPublicationDisposition.RolledBack ||
                outcome.Failure is InvalidDataException || outcome.Failure == null ||
                !IsTransientFileAccessException(outcome.Failure) || attempt >= TransientFileAccessRetryCount - 1)
                return outcome;
            await Task.Delay(TransientFileAccessRetryDelay, cancellationToken);
            VerifyCurrentSessionOperation(lease);
        }
    }
    finally
    {
        foreach (var registration in registrations) registration.Dispose();
    }
}

internal void RequireCommittedLocalPublication(TrustedLocalPublicationOutcome outcome)
{
    if (outcome.Disposition == TrustedLocalPublicationDisposition.Committed)
    {
        if (outcome.Failure != null)
        {
            try { _logger.LogWarning(outcome.Failure, "Local publication committed; journal cleanup remains pending."); }
            catch { /* Diagnostic transport cannot reverse an established committed result. */ }
        }
        return;
    }
    if (outcome.Disposition == TrustedLocalPublicationDisposition.RolledBack && outcome.Failure != null)
        ExceptionDispatchInfo.Capture(outcome.Failure).Throw();
    throw new CoordinatedStatePublicationUncertainException(outcome.Failure);

private async Task WriteTrustedLocalFileAsync(CanonicalWriteLease lease, string relativePath, byte[]? desired)
{
    RequireCommittedLocalPublication(await PublishOrdinaryFileWithOutcomeAsync(lease, relativePath, desired));
}

// The ordinary facade and retained script command use the same publication.
// Returning its original outcome permits capture before facade throw/lease close.
internal async Task<TrustedLocalPublicationOutcome> PublishOrdinaryFileWithOutcomeAsync(
    CanonicalWriteLease lease, string relativePath, byte[]? desired)
{
    EnsureWorkerGeneralMutationAllowed(lease);
    lease.EnsureNoPendingLocalDecision();
    if (!UsesTrustedLocalWriter(lease, relativePath))
        throw new InvalidOperationException("An ordinary outcome requires the current local writer.");
    var before = await ReadLocalFileBytesAsync(lease, relativePath);
    return await PublishLocalFilesAsync(lease, [new(relativePath, before, desired)]);

  public async Task<bool> WriteManifestForGmAsync()
  {
      var lease = await _fs.AcquireCanonicalWriteLeaseAsync();
      CoordinatedStatePublicationUncertainException? uncertainty = null;
      var completed = false;
      try
      {
          var mods = await ReadAvailableModsAsync(lease, _settings.EnabledSystemMods);
          var normalizedEnabled = mods
              .Where(mod => mod.Enabled)
              .Select(mod => mod.FileName)
              .Distinct(StringComparer.OrdinalIgnoreCase)
              .ToList();

          var changed = !_settings.EnabledSystemMods.SequenceEqual(normalizedEnabled, StringComparer.OrdinalIgnoreCase);
          var manifest = BuildManifestNode(mods, normalizedEnabled);
          var currentJson = await _fs.ReadFileAsync(lease, ManifestPath);
          if (!SemanticallyMatchesExistingManifest(currentJson, manifest))
          {
              manifest["_lastUpdated"] = DateTime.UtcNow.ToString("o");
              await _fs.WriteFileAtomicAsync(lease, ManifestPath, manifest.ToJsonString(JsonOpts));
          }

          _settings.EnabledSystemMods = normalizedEnabled;
          completed = true;
          return changed;
      }
      catch (CoordinatedStatePublicationUncertainException failure) { uncertainty = failure; throw; }
      finally { await CoordinatedStateWriteHelper.ReleaseOwnedLeaseAsync(_fs, lease, completed, uncertainty); }
  }

  private static JsonObject BuildManifestNode(
      IReadOnlyCollection<SystemModDescriptor> mods,
      IReadOnlyList<string> normalizedEnabled)
  {
      var activeMods = new JsonArray();
      foreach (var mod in mods.Where(mod => mod.Enabled))
      {
          activeMods.Add(new JsonObject
          {
              ["fileName"] = mod.FileName,
              ["relativePath"] = mod.RelativePath,
              ["modId"] = mod.ModId,
              ["name"] = mod.Name,
              ["description"] = mod.Description,
              ["extension"] = mod.Extension,
              ["lastModifiedUtc"] = mod.LastModifiedUtc,
              ["content"] = mod.Content
          });
      }

      var availableMods = new JsonArray();
      foreach (var mod in mods)
      {
          availableMods.Add(new JsonObject
          {
              ["fileName"] = mod.FileName,
              ["relativePath"] = mod.RelativePath,
              ["modId"] = mod.ModId,
              ["name"] = mod.Name,
              ["description"] = mod.Description,
              ["extension"] = mod.Extension,
              ["lastModifiedUtc"] = mod.LastModifiedUtc,
              ["enabled"] = mod.Enabled
          });
      }

      var enabledMods = new JsonArray();
      foreach (var fileName in normalizedEnabled)
          enabledMods.Add(fileName);

      return new JsonObject
      {
          ["modsDirectory"] = ModsDirectory,
          ["activeCount"] = mods.Count(mod => mod.Enabled),
          ["totalCount"] = mods.Count,
          ["enabledSystemMods"] = enabledMods,
          ["activeMods"] = activeMods,
          ["availableMods"] = availableMods
      };
  }

  private static bool SemanticallyMatchesExistingManifest(string? currentJson, JsonObject expectedManifest)
  {
      if (string.IsNullOrWhiteSpace(currentJson))
          return false;

      try
      {
          if (JsonNode.Parse(currentJson) is not JsonObject currentManifest)
              return false;

          currentManifest.Remove("_lastUpdated");
          return JsonNode.DeepEquals(currentManifest, expectedManifest);
      }
      catch
      {
          return false;
      }
  }

  public async Task<string> BuildSystemReminderFragmentAsync()
  {
      var mods = await GetAvailableModsAsync(includeContent: false);
      var activeMods = mods.Where(mod => mod.Enabled).ToList();

      if (activeMods.Count == 0)
      {
          return @"SYSTEM MODS:
- No active global system mods are enabled for this session.
- Ignore files in game_session/mods unless they appear in game_state/core/system_mods.json.activeMods[].";
      }

      var lines = new List<string>
      {
          "SYSTEM MODS:",
          "  - Read game_state/core/system_mods.json before authoring the turn.",
          "  - Only activeMods[] are canonical; ignore disabled files in game_session/mods.",
          "  - Each active mod applies globally unless the mod text narrows its own scope.",
          "  - Active mods for this session:"
      };

      foreach (var mod in activeMods)
      {
          var line = $"    • {mod.Name} ({mod.FileName})";
          if (!string.IsNullOrWhiteSpace(mod.Description))
              line += $" — {mod.Description}";
          lines.Add(line);
      }

      return string.Join(Environment.NewLine, lines);

internal async Task<IReadOnlyList<SystemModDescriptor>> ReadAvailableModsAsync(
    FileSystemManager.CanonicalWriteLease lease, IReadOnlyCollection<string> enabledFiles)
{
    ArgumentNullException.ThrowIfNull(enabledFiles);
    _fs.EnsureCanonicalWriteLeaseActive(lease);
    _fs.VerifyCurrentSessionOperation(lease);
    var modsDirectory = GetModsDirectoryPath();
    // Construction validates every ancestor and the root itself without
    // creating an absent directory or traversing a linked directory.
    var scope = new TrustedLocalFileScope([modsDirectory]);
    var enabled = new HashSet<string>(enabledFiles, StringComparer.OrdinalIgnoreCase);
    var mods = new List<SystemModDescriptor>();
    if (Directory.Exists(modsDirectory))
    {
        var files = Directory.EnumerateFiles(modsDirectory, "*.*", SearchOption.TopDirectoryOnly)
            .Where(path => SupportedExtensions.Contains(Path.GetExtension(path), StringComparer.OrdinalIgnoreCase))
            .OrderBy(path => Path.GetFileName(path), StringComparer.OrdinalIgnoreCase)
            .ToArray();
        foreach (var file in files)
        {
            var path = scope.ValidateFile(file, allowMissing: false);
            var fileName = Path.GetFileName(path);
            var bytes = await _fs.ReadLocalFileBytesAsync(lease, $"{ModsDirectory}/{fileName}")
                ?? throw new FileNotFoundException("A mod input disappeared during settings preparation.", path);
            mods.Add(BuildDescriptor(path, LocalSettingsPreparation.DecodeText(bytes), includeContent: true, enabled.Contains(fileName)));
        }
    }
    _fs.VerifyCurrentSessionOperation(lease);
    return mods;
}

