    try
    {
        return StrictJsonAuthority.Deserialize<QteRuntimeState>(
                   json,
                   JsonOpts,
                   "QTE runtime") ??
               throw new InvalidDataException(
                   "qte_runtime.json contains a null QTE authority root.");
